<?php require_once __DIR__.'/includes/permissions.php';require_permission('programs.manage');$pdo=db();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=post('action');if($a==='save'){$id=(int)post('id',0);$data=[trim((string)post('name')),trim((string)post('description')),post('start_date')?:null,post('end_date')?:null,post('status','Planned')];if(!$data[0])throw new Exception('Program name is required.');if($id){$pdo->prepare('UPDATE health_programs SET name=?,description=?,start_date=?,end_date=?,status=? WHERE id=?')->execute([...$data,$id]);audit('UPDATE','health_programs',$id,'Program updated');}else{$pdo->prepare('INSERT INTO health_programs(name,description,start_date,end_date,status,created_by) VALUES(?,?,?,?,?,?)')->execute([...$data,current_user()['id']]);audit('CREATE','health_programs',(int)$pdo->lastInsertId(),'Program created');}flash('success','Program saved.');redirect(BASE_URL.'/programs.php');}elseif($a==='archive'){$id=(int)post('id');$pdo->prepare('UPDATE health_programs SET status="Archived" WHERE id=?')->execute([$id]);audit('ARCHIVE','health_programs',$id,'Program archived');flash('success','Program archived.');redirect(BASE_URL.'/programs.php');}}catch(Throwable $e){$error=$e->getMessage();}}$rows=$pdo->query('SELECT * FROM health_programs ORDER BY created_at DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Health Programs</h1><p>Manage CHO community health programs.</p></div></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="panel mb-4"><div class="panel-head"><h5>Add Program</h5></div><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="save"><div class="col-md-4"><label>Name *</label><input name="name" class="form-control" required></div><div class="col-md-4"><label>Description</label><input name="description" class="form-control"></div><div class="col-md-2"><label>Start</label><input type="date" name="start_date" class="form-control"></div><div class="col-md-2"><label>End</label><input type="date" name="end_date" class="form-control"></div><div class="col-md-3"><label>Status</label><select name="status" class="form-select"><?php foreach(['Planned','Active','Completed','Archived'] as $s):?><option><?=$s?></option><?php endforeach;?></select></div><div class="col-12"><button class="btn btn-primary">Save Program</button></div></form></div><div class="panel"><div class="panel-head"><h5>Programs</h5><input class="form-control table-search" placeholder="Search..." data-table-search="programsTable"></div><div class="table-responsive"><table class="table" id="programsTable"><thead><tr><th>Name</th><th>Description</th><th>Dates</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['description'])?></td><td><?=e(($r['start_date']??'—').' to '.($r['end_date']??'—'))?></td><td><span class="badge text-bg-secondary"><?=e($r['status'])?></span></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="archive"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-secondary">Archive</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/includes/footer.php'; ?>
